contract InvMutTest {
    C c;

    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address to, uint256 value) public payable {
        address from = address(this);
        uint256 fromBefore = c.balanceOf(from); if (__ESBMC_reverted()) return;
        uint256 toBefore = c.balanceOf(to); if (__ESBMC_reverted()) return;
        bool frozenFrom = c.frozenAccount(from); if (__ESBMC_reverted()) return;
        bool frozenTo = c.frozenAccount(to); if (__ESBMC_reverted()) return;

        require(to != address(0));
        require(to != from);
        require(!frozenFrom);
        require(!frozenTo);
        require(fromBefore >= value);
        require(c.frozenAccount(to) == frozenTo);
        require(c.frozenAccount(from) == frozenFrom);

        bool reverted;
        c.transfer(to, value); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 fromAfter = c.balanceOf(from); if (__ESBMC_reverted()) return;
        uint256 toAfter = c.balanceOf(to); if (__ESBMC_reverted()) return;

        assert(!reverted && fromAfter + value == fromBefore && toAfter == toBefore + value);
    }

    receive() external payable {}
}

